-- Verificação de segurança: as 378 comunas AO têm de estar ligadas ao município.
do $$
declare v int; v_bad int;
begin
  select count(*) into v from public.administrative_divisions where country_code='AO' and level=3 and parent_level=2;
  if v <> 378 then raise exception 'Esperava 378 comunas com parent município, obtive %', v; end if;
  -- todos os parent_code apontam para um município AO existente?
  select count(*) into v_bad from public.administrative_divisions c
    where c.country_code='AO' and c.level=3
      and not exists (select 1 from public.administrative_divisions m
                       where m.code=c.parent_code and m.level=2 and m.country_code='AO');
  if v_bad > 0 then raise exception '% comunas com município inexistente', v_bad; end if;
  raise notice 'OK: 378 comunas ligadas ao município.';
end $$;

commit;
